"use strict";(self.webpackChunkdg_knowlege_base=self.webpackChunkdg_knowlege_base||[]).push([[7761],{84355:i=>{i.exports=JSON.parse('{"tag":{"label":"Dashboards","permalink":"/datagol-knowlegde-base-v1/docs/tags/dashboards","allTagsPath":"/datagol-knowlegde-base-v1/docs/tags","count":36,"items":[{"id":"BI Analytics/Drill Down/Drill Down","title":"About Drill-Down","description":"Drill-down is a powerful data exploration technique that lets you move from a high-level summary to more detailed views. In dashboards or reports, you can click on a data point (like a bar, metric, or chart segment) to reveal deeper layers of information. This helps you quickly investigate trends, spot anomalies, and understand performance breakdowns\u2014all without leaving your dashboard.","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Drill Down/"},{"id":"BI Analytics/Visualizer/About Visualizer","title":"About Visualizer","description":"The Visualizer is a crucial component for performing Business Intelligence (BI) Analytics. It\'s where you actively engage in data visualization to transform raw data into actionable insights, ultimately driving data-driven decision-making.","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Visualizer/about-visualizer"},{"id":"BI Analytics/Widgets/Widget configurations and settings/Widget Configuration and Settings","title":"About widget configuration and settings","description":"DataGOL offers a flexible way to visualize your data through configurable widgets.","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Widgets/Widget configurations and settings/Widget Configuration and Settings"},{"id":"BI Analytics/Visualizer/Aggregate functions","title":"Aggregate functions","description":"Aggregate functions are calculations performed on a set of values to produce a single summary value. They are incredibly useful for gaining insights from large datasets by condensing information into meaningful metrics. In effect you are prompting the Visualizer to take a numerical column, perform a specific calculation (Sum, Max, Min, Average, Count, Unique Count etc.) on its values, and then display the results grouped by the categories in this other column.","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Visualizer/aggregate-functions"},{"id":"BI Analytics/Alerts","title":"Alerts","description":"Alerting is a core feature in DataGOL that allows you to create alerts and notifications in DataGOL for tracking key performance indicators (KPIs) effectively.","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Alerts"},{"id":"BI Analytics/Widgets/Widget configurations and settings/Area chart widget","title":"Area chart widget","description":"Configuring Area chart widget","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Widgets/Widget configurations and settings/area-chart-widget-configuration-settings"},{"id":"BI Analytics/Widgets/Widget configurations and settings/Bar chart widget","title":"Bar chart widget","description":"Configuring Bar chart widget","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Widgets/Widget configurations and settings/bar-chart-widget-configuration-settings"},{"id":"BI Analytics/Formulas & Parameters/BI Formula","title":"BI Formulas","description":"What Are Formulas in DataGOL?","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Formulas & Parameters/BI Formula"},{"id":"BI Analytics/Widgets/Widget configurations and settings/Box plot widget","title":"Box plot widget","description":"Configuring Box plot widget","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Widgets/Widget configurations and settings/box-plot-widget-configuration-settings"},{"id":"BI Analytics/Column Aggregation","title":"Column Aggregations","description":"In DataGOL, users can apply various aggregation types to columns to summarize and analyze data effectively. These aggregations help transform raw values into meaningful insights \u2014 such as totals, averages, trends, and patterns.","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Column Aggregation"},{"id":"Workbooks/Conditional formatting for tables","title":"Conditional formatting for tables","description":"Enhance your data analysis with the new conditional formatting feature for tables and pivot tables. You can now define custom rules and dynamically color-code cells based on their values, allowing for quick visual identification of key data points that meet specific thresholds or criteria.","permalink":"/datagol-knowlegde-base-v1/docs/Workbooks/conditional-format"},{"id":"BI Analytics/Visualizer/Creating visualization or widget","title":"Creating visualization or widget","description":"1.  Select a workbook to visualize data. You can choose one of the following types of workbooks:","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Visualizer/create-visualization-or-create-widget"},{"id":"BI Analytics/Widgets/Widget configurations and settings/Donut chart widget","title":"Donut chart widget","description":"Configuring Donut chart widget","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Widgets/Widget configurations and settings/donut-chart-widget-configuration-settings"},{"id":"BI Analytics/Drill Down/Drill Down Journey","title":"Drill Down Journey","description":"What is Drill Down Journey ?","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Drill Down/Drill Down Journey"},{"id":"BI Analytics/Drill Down/Drill Down - Widget","title":"Drill Down Widget","description":"Widget drill down","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Drill Down/Drill Down - Widget"},{"id":"BI Analytics/Drill Down/Drill Down-ad hoc","title":"Drill Down- Ad Hoc","description":"What is Ad-Hoc Drill-Down?","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Drill Down/Drill Down-ad hoc"},{"id":"BI Analytics/Widgets/Widget configurations and settings/Funnel chart widget","title":"Funnel chart widget","description":"Configuring Funnel chart widget","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Widgets/Widget configurations and settings/funnel-chart-widget-configuration-settings"},{"id":"BI Analytics/Widgets/Widget configurations and settings/KPI widget","title":"KPI widget","description":"Configuring KPI widget","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Widgets/Widget configurations and settings/kpi-widget-configuration-settings"},{"id":"BI Analytics/Widgets/Widget configurations and settings/Line chart widget","title":"Line chart widget","description":"Configuring Line chart widget","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Widgets/Widget configurations and settings/line-chart-widget-configuration-settings"},{"id":"BI Analytics/Widgets/Widget configurations and settings/Packed bubble chart widget","title":"Packed bubble chart widget","description":"Configuring Packed Bubble chart widget","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Widgets/Widget configurations and settings/packed-bubble-chart-widget-configuration-settings"},{"id":"BI Analytics/Formulas & Parameters/Parameters","title":"Parameters","description":"In DataGOL,Parameters are dynamic input placeholders\u2014such as a number, text, date, or boolean\u2014that replace hardcoded values in formulas or BI Workbooks. They allow users to adjust values on the fly in dashboards or visualizations without editing the actual SQL or underlying dataset.","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Formulas & Parameters/Parameters"},{"id":"BI Analytics/Widgets/Widget configurations and settings/Pie chart widget","title":"Pie chart widget","description":"Configuring Pie chart widget","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Widgets/Widget configurations and settings/pie-chart-widget-configuration-settings"},{"id":"BI Analytics/Visualizer/Save widget/Pinning visualization to dashboard","title":"Pinning visualization to dashboard","description":"After you have created a visualization or widget, you can pin it to the dashboards.","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Visualizer/Save widget/pin-widget-to-dashboard"},{"id":"BI Analytics/Widgets/Widget configurations and settings/Pivot table widget","title":"Pivot table widget","description":"Configuring Pivot table widget  - configuration and setting","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Widgets/Widget configurations and settings/pivot-table-widget-configuration-settings"},{"id":"BI Analytics/Visualizer/Save widget/Saving visualization as draft","title":"Saving visualization as draft","description":"Drafting a visualization allows you to save your progress and continue working on it later without losing any changes. This is particularly useful when you are in the middle of creating a complex visualization and need to step away. Saving it as a draft ensures your work is securely stored, so you can pick up right where you left off.","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Visualizer/Save widget/save-visualization-as-drafts"},{"id":"BI Analytics/Widgets/Widget configurations and settings/Scatter chart widget","title":"Scatter chart widget","description":"Configuring Scatter chart widget","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Widgets/Widget configurations and settings/scatter-chart-widget-configuration-settings"},{"id":"BI Analytics/Visualizer/Select workbook","title":"Selecting source/workbooks","description":"To begin visualizing data, you must first select a workbook as follows:","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Visualizer/Select workbook"},{"id":"BI Analytics/Widgets/Widget configurations and settings/Table widget","title":"Table widget","description":"","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Widgets/Widget configurations and settings/table-widget-configuration-settings"},{"id":"BI Analytics/Theming","title":"Theming","description":"Theming of embedded dashboards or third-party sharing dashboards involves customizing their appearance to match the host application\'s look and feel. This process ensures a consistent and seamless user experience, making the embedded dashboard feel like a natural part of the application rather than a separate tool. This is particularly useful for maintaining brand consistency.","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/set-theme-third-party-embedded-dashboards"},{"id":"BI Analytics/Time Travel","title":"Time Travel","description":"","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Time Travel"},{"id":"BI Analytics/Widgets/Widget configurations and settings/Tree map chart widget","title":"Tree map chart widget","description":"Configuring Tree map chart widget","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Widgets/Widget configurations and settings/tree-map-chart-widget-configuration-settings"},{"id":"BI Analytics/Visualizer/Select Columns","title":"Understanding columns","description":"Once the workbook is selected, the next step is to identify and add the desired columns to be visualized.","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Visualizer/Select Columns"},{"id":"BI Analytics/Visualizer/Understanding Visualizer","title":"Understanding the Visualizer","description":"This topic introduces the user interface (UI) for data visualization. It describes the individual components of the visualizer\'s interface and explains the function of each part. Each of the functions are referenced to the corresponding topics.","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Visualizer/Understanding Visualizer"},{"id":"BI Analytics/Visualizer/Details Panel","title":"Viewing the Data Details panel","description":"The Details panel provides in-depth information about the SQL query that powers your current widget. This panel is essential for users who want to understand exactly how their data is being fetched, filtered, and transformed.","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Visualizer/Details Panel"},{"id":"BI Analytics/Widgets/Widget Filters","title":"Widget Filters","description":"In the Visualizer, you can add filters at the widget level to refine the data displayed in your visualizations.","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Widgets/Widget Filters"},{"id":"BI Analytics/Widgets/Widget Types","title":"Widget Types","description":"This guide outlines the data visualization possibilities within our BI tool. Understand how to combine your data columns with different widgets to uncover insights. This guide will help a business user understand what visualizations they can expect to be suggested and how their data (Dimensions, Metrics, Date Times) will generally be used if they pick that suggestion.","permalink":"/datagol-knowlegde-base-v1/docs/BI Analytics/Widgets/Widget Types"}],"unlisted":false}}')}}]);